# Surah At-Tawbah (chapter 9) — part 5: ayat 41-49 (IDs 1276-1284)
SURAH = 9

ENTRIES = {
1276: (
"ہلکے اور بوجھل — دونوں حالتوں — میں — نکل جاؤ — اور — اللہ کی راہ میں — اپنے مالوں اور جانوں کے ساتھ — جہاد کرو — یہ — تمہارے لیے بہتر ہے — اگر — تم — جانتے ہو",
"""۱۔ جہاد — ہر حال میں — بغیر کسی بہانے۔
۲۔ ’’انفِرُوا خِفَافًا وَثِقَالًا وَجَاهِدُوا بِأَمْوَالِكُمْ وَأَنفُسِكُمْ فِي سَبِيلِ اللَّهِ ذَٰلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ‘‘ — ہلکے اور بوجھل — دونوں حالتوں — میں — نکل جاؤ — اور — اللہ کی راہ میں — اپنے مالوں اور جانوں کے ساتھ — جہاد کرو — یہ — تمہارے لیے بہتر ہے — اگر — تم — جانتے ہو — یعنی جہاد — چاہے — آپ ہلکے ہوں یا بوجھل — مال و جان — دونوں کے ساتھ — کرنا واجب ہے۔
۳۔ عملی سبق: جہاد — بہانہ — مانگتا نہیں؛ فرض ہے۔"""
),
1277: (
"اگر — منافع — قریب اور — سفر — آسان — ہوتا — تو — وہ — تمہارے پیچھے — آ جاتے — لیکن — ان پر — راہ — دور پڑ گئی — اور — وہ — عنقریب — اللہ کی قسم — کھا کر کہیں گے — اگر — ہم استطاعت رکھتے — تو — تمہارے ساتھ نکلتے — وہ — اپنی جانوں کو ہلاک کرتے ہیں — اور — اللہ — جانتا ہے کہ — وہ — جھوٹے ہیں",
"""۱۔ منافقوں کے بہانے — جھوٹے۔
۲۔ ’’لَوْ كَانَ عَرَضًا قَرِيبًا وَسَفَرًا قَاصِدًا لَّاتَّبَعُوكَ وَلَٰكِن بَعُدَتْ عَلَيْهِمُ الشُّقَّۃُ وَسَيَحْلِفُونَ بِاللَّهِ لَوِ اسْتَطَعْنَا لَخَرَجْنَا مَعَكُمْ يُهْلِكُونَ أَنفُسَهُمْ وَاللَّهُ يَعْلَمُ إِنَّهُمْ لَكَاذِبُونَ‘‘ — اگر — منافع — قریب اور — سفر — آسان — ہوتا — تو — وہ — تمہارے پیچھے — آ جاتے — لیکن — ان پر — راہ — دور پڑ گئی — اور — وہ — عنقریب — اللہ کی قسم — کھا کر کہیں گے — اگر — ہم استطاعت رکھتے — تو — تمہارے ساتھ نکلتے — وہ — اپنی جانوں کو ہلاک کرتے ہیں — اور — اللہ — جانتا ہے کہ — وہ — جھوٹے ہیں — یعنی منافق — اگر راستہ آسان ہوتا — تو جہاد میں شامل ہوتے — مگر — دور جانے سے — ڈر گئے — اور — جھوٹی قسمیں کھاتے ہیں۔
۳۔ عملی سبق: بہانے — دل میں — کچھ اور — زبان پر کچھ — مگر — اللہ — سب جانتا ہے۔"""
),
1278: (
"اللہ — نے — آپؐ — سے — درگزر فرمایا — آپ نے — انہیں — کیوں — اجازت دی — یہاں تک کہ — آپ — ان — کو دیکھیں — جو سچے ہیں — اور — جھوٹوں کو بھی — جان لیں",
"""۱۔ نبیؐ کو — منافقوں کو اجازت دینے پر تنبیہ۔
۲۔ ’’عَفَا اللَّهُ عَنكَ لِمَ أَذِنتَ لَهُمْ حَتَّىٰ يَتَبَيَّنَ لَكَ الَّذِينَ صَدَقُوا وَتَعْلَمَ الْكَاذِبِينَ‘‘ — اللہ — نے — آپؐ — سے — درگزر فرمایا — آپ نے — انہیں — کیوں — اجازت دی — یہاں تک کہ — آپ — ان — کو دیکھیں — جو سچے ہیں — اور — جھوٹوں کو بھی — جان لیں — یعنی نبیؐ کو تنبیہ کی گئی کہ — اجازت دینے سے پہلے — سچ اور جھوٹ — کی تمیز ہونی چاہیے تھی۔
۳۔ عملی سبق: کسی کی بات پر — آنکھ بند کر کے یقین نہ کرو؛ تفتیش کرو۔"""
),
1279: (
"آپ سے — اجازت — نہیں مانگتے — وہ — لوگ — جو — اللہ اور آخرت کے دن — پر ایمان لاتے ہیں — اپنے مالوں اور جانوں کے ساتھ — جہاد — کی — اور — اللہ — متقیوں — کو — جانتا ہے",
"""۱۔ سچے مؤمن — جہاد کے لیے — اجازت نہیں مانگتے۔
۲۔ ’’لَّا يَسْتَأْذِنُكَ الَّذِينَ يُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ أَن يُجَاهِدُوا بِأَمْوَالِهِمْ وَأَنفُسِهِمْ وَاللَّهُ عَلِيمٌ بِالْمُتَّقِينَ‘‘ — آپ سے — اجازت — نہیں مانگتے — وہ — لوگ — جو — اللہ اور آخرت کے دن — پر ایمان لاتے ہیں — اپنے مالوں اور جانوں کے ساتھ — جہاد — کی — اور — اللہ — متقیوں — کو — جانتا ہے — یعنی سچے مؤمن — خود — جہاد کے لیے نکل کھڑے ہوتے ہیں — بہانے نہیں بناتے۔
۳۔ عملی سبق: سچا مؤمن — جہاد کے لیے — خود آگے بڑھتا ہے۔"""
),
1280: (
"صرف — وہ — آپ سے — اجازت مانگتے ہیں — جو — اللہ اور آخرت کے دن — پر ایمان نہیں لاتے — اور — ان کے دل — شک — میں — پڑے ہیں — پس — وہ — اپنے شک میں — ڈگمگا رہے ہیں",
"""۱۔ منافق — اجازت مانگنے والے — شک میں ڈگمگاتے ہیں۔
۲۔ ’’إِنَّمَا يَسْتَأْذِنُكَ الَّذِينَ لَا يُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ وَارْتَابَتْ قُلُوبُهُمْ فَهُمْ فِي رَيْبِهِمْ يَتَرَدَّدُونَ‘‘ — صرف — وہ — آپ سے — اجازت مانگتے ہیں — جو — اللہ اور آخرت کے دن — پر ایمان نہیں لاتے — اور — ان کے دل — شک — میں — پڑے ہیں — پس — وہ — اپنے شک میں — ڈگمگا رہے ہیں — یعنی منافق — شک اور تردد — میں رہتے ہیں — اس لیے — جہاد سے — بچنے کے بہانے ڈھونڈتے ہیں۔
۳۔ عملی سبق: شک میں — ایمان کامل نہیں ہوتا؛ یقین سے — آگے بڑھو۔"""
),
1281: (
"اور — اگر — وہ — نکلنے کا ارادہ کرتے — تو — اس — کے لیے تیاری کرتے — لیکن — اللہ — کو ان کا نکلنا — ناپسند تھا — پس — اس — نے — انہیں — روک دیا — اور — کہا گیا — بیٹھ جاؤ — بیٹھنے والوں کے ساتھ",
"""۱۔ منافق — نکلنے کا ارادہ ہی — نہیں رکھتے تھے۔
۲۔ ’’وَلَوْ أَرَادُوا الْخُرُوجَ لَأَعَدُّوا لَهُ عُدَّۃً وَلَٰكِن كَرِهَ اللَّهُ انبِعَاثَهُمْ فَثَبَّطَهُمْ وَقِيلَ اقْعُدُوا مَعَ الْقَاعِدِينَ‘‘ — اور — اگر — وہ — نکلنے کا ارادہ کرتے — تو — اس — کے لیے تیاری کرتے — لیکن — اللہ — کو ان کا نکلنا — ناپسند تھا — پس — اس — نے — انہیں — روک دیا — اور — کہا گیا — بیٹھ جاؤ — بیٹھنے والوں کے ساتھ — یعنی منافق — جہاد کے لیے — پوری تیاری — کر رہے ہوتے تو — انہیں روکنا نہ پڑتا — مگر — اللہ — کو ان کا نکلنا — ناپسند تھا۔
۳۔ عملی سبق: نفاق — دل سے — نکلتا ہے؛ اعمال — سب بتاتے ہیں۔"""
),
1282: (
"اگر — وہ — تمہارے ساتھ — نکلتے — تو — تمہیں — صرف — فساد — میں اضافہ کرتے — اور — تمہارے درمیان — تیزی سے بھاگتے — تمہیں — فتنے — میں — ڈالنے کے لیے — اور — تم میں — کچھ — ان — کی — بات — ماننے والے — بھی — ہیں — اور — اللہ — ظالموں — کو — جانتا ہے",
"""۱۔ منافقوں کی شرکت — فساد کا سبب تھی۔
۲۔ ’’لَوْ خَرَجُوا فِيكُم مَّا زَادُوكُمْ إِلَّا خَبَالًا وَلَأَوْضَعُوا خِلَالَكُمْ يَبْغُونَكُمُ الْفِتْنَۃَ وَفِيكُمْ سَمَّاعُونَ لَهُمْ وَاللَّهُ عَلِيمٌ بِالظَّالِمِينَ‘‘ — اگر — وہ — تمہارے ساتھ — نکلتے — تو — تمہیں — صرف — فساد — میں اضافہ کرتے — اور — تمہارے درمیان — تیزی سے بھاگتے — تمہیں — فتنے — میں — ڈالنے کے لیے — اور — تم میں — کچھ — ان — کی — بات — ماننے والے — بھی — ہیں — اور — اللہ — ظالموں — کو — جانتا ہے — یعنی منافقیں — جنگ میں شامل ہو کر — فساد اور فتنہ — پھیلاتے۔
۳۔ عملی سبق: دشمنی دل میں — جان کر — اجنبی کی قربت قبول نہ کرو۔"""
),
1283: (
"بے شک — انہوں نے — اس سے پہلے — فتنہ — پھیلانے کی کوشش کی — اور — آپؐ کے لیے — معاملات — کو उलट پلٹ کیا — یہاں تک کہ — حق آ گیا — اور — اللہ کا حکم — ظاہر ہو گیا — حالانکہ — وہ — ناپسند کرتے تھے",
"""۱۔ منافق — ہمیشہ — فتنہ — پھیلانے — والے۔
۲۔ ’’لَقَدِ ابْتَغَوُا الْفِتْنَۃَ مِن قَبْلُ وَقَلَّبُوا لَكَ الْأُمُورَ حَتَّىٰ جَاءَ الْحَقُّ وَظَهَرَ أَمْرُ اللَّهِ وَهُمْ كَارِهُونَ‘‘ — بے شک — انہوں نے — اس سے پہلے — فتنہ — پھیلانے کی کوشش کی — اور — آپؐ کے لیے — معاملات — کو उलट پلٹ کیا — یہاں تک کہ — حق آ گیا — اور — اللہ کا حکم — ظاہر ہو گیا — حالانکہ — وہ — ناپسند کرتے تھے — یعنی منافق — پہلے بھی — رسولؐ کے خلاف — سازشیں کر چکے ہیں؛ مگر — اللہ — نے — حق کو — ظاہر کیا۔
۳۔ عملی سبق: فتنے — آخرکار — اللہ کی قدرت سے — ناکام — ہوتے ہیں۔"""
),
1284: (
"اور ان میں — کوئی — کہتا ہے — مجھے اجازت دے — اور — مجھے فتنے میں نہ ڈال — خبردار — وہ — فتنے — میں — پڑ گئے — اور — بے شک — جہنم — کافروں کو — گھیرے ہوئے ہے",
"""۱۔ منافق — خود — فتنے میں مبتلا — ہیں۔
۲۔ ’’وَمِنْهُم مَّن يَقُولُ ائْذَن لِّي وَلَا تَفْتِنِّي أَلَا فِي الْفِتْنَۃِ سَقَطُوا وَإِنَّ جَهَنَّمَ لَمُحِيطَۃٌ بِالْكَافِرِينَ‘‘ — اور ان میں — کوئی — کہتا ہے — مجھے اجازت دے — اور — مجھے فتنے میں نہ ڈال — خبردار — وہ — فتنے — میں — پڑ گئے — اور — بے شک — جہنم — کافروں کو — گھیرے ہوئے ہے — یعنی منافق — بہانہ بناتا ہے — کہ — وہ — فتنہ میں نہ پڑے — مگر — وہ خود — فتنے میں — پڑ چکا ہے۔
۳۔ عملی سبق: بہانے — خود فتنہ ہیں؛ ایمان سے — گریز — سب سے بڑا فتنہ ہے۔"""
),
}
